import json
import sys
import time
import urllib.error
import urllib.request

BASE = "http://localhost:8080"
OUT = "/tmp/recon/raw.json"


class Client:
    def __init__(self):
        self.token = None
        self.log = []

    def new_token(self):
        req = urllib.request.Request(BASE + "/token", method="POST")
        with urllib.request.urlopen(req, timeout=30) as r:
            self.token = json.load(r)["token"]

    def get(self, path, auth=True):
        attempts = 0
        while True:
            attempts += 1
            if attempts > 200:
                raise RuntimeError(f"gave up on {path}")
            if auth and self.token is None:
                self.new_token()
            headers = {"Authorization": f"Bearer {self.token}"} if auth else {}
            req = urllib.request.Request(BASE + path, headers=headers)
            try:
                with urllib.request.urlopen(req, timeout=30) as r:
                    body = r.read()
                    self.log.append((path, r.status))
                    return json.loads(body)
            except urllib.error.HTTPError as e:
                body = e.read().decode("utf-8", "replace")
                self.log.append((path, e.code, body[:200]))
                if e.code == 401:
                    self.new_token()
                    continue
                if e.code == 404:
                    return None
                if e.code == 429:
                    wait = e.headers.get("Retry-After")
                    if wait is None:
                        try:
                            wait = json.loads(body).get("retry_after")
                        except Exception:
                            wait = None
                    wait = float(wait) if wait is not None else 5.0
                    print(f"429 on {path}; sleeping {wait}s", file=sys.stderr)
                    time.sleep(wait + 0.5)
                    continue
                print(f"HTTP {e.code} on {path}: {body[:200]}; retrying", file=sys.stderr)
                time.sleep(min(2 ** min(attempts, 6), 60))
            except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
                print(f"network error on {path}: {e}; retrying", file=sys.stderr)
                time.sleep(min(2 ** min(attempts, 6), 60))


def main():
    c = Client()
    pages = {}
    page = 1
    total_pages = None
    while True:
        data = c.get(f"/orders?page={page}")
        pages[page] = data
        total_pages = data["total_pages"]
        print(f"page {page}/{total_pages}: {len(data['items'])} items", file=sys.stderr)
        if page >= total_pages or data.get("next") is None and page >= total_pages:
            break
        page += 1

    customers = {}
    for cid in sorted({o["customer_id"] for p in pages.values() for o in p["items"]}):
        customers[cid] = c.get(f"/customers/{cid}")

    with open(OUT, "w") as f:
        json.dump({"pages": pages, "customers": customers, "log_tail": c.log[-50:]}, f)
    print(f"saved {OUT}; requests logged: {len(c.log)}", file=sys.stderr)


if __name__ == "__main__":
    main()

